		bd, err := row.bind(fx)
		if err != nil {
			t.Fatalf("ProveRanked: %v", err)
		}
		bound = append(bound, bd)
		if row.ProvenBy == nil {
			continue
		}
		sub, err := row.ProvenBy.Subject()
